pure fn vault(m: HashMap<u64, u64>, k: u64) -> u64 {
    let band = {
        let slot = m[k];
        if m.exists(k) { slot } else { 0 }
    };
    match k {
        0 => band,
        _ => {
            let span = 0..k;
            if m.exists(k) { m[k] + span.end } else { 0 }
        }
    }
}

